// VectorSearch 组件源码 —— 由 build.mjs 注入运行时字符串后生成 dist/components/index.js
// 占位符（引擎源码与样式的注入点）会被 build.mjs 替换为 JSON 字符串字面量。
import { h } from "preact"

const classNames = (...classes) => classes.filter(Boolean).join(" ")

export const VectorSearch = (userOpts = {}) => {
  const Component = ({ displayClass }) => {
    const placeholder = userOpts.placeholder || "语义搜索…"
    return h("div", { class: classNames(displayClass, "vector-search") }, [
      h("input", {
        class: "search-bar",
        type: "text",
        autocomplete: "off",
        "aria-label": placeholder,
        placeholder,
      }),
      h("div", { class: "vector-results" }),
    ])
  }
  Component.displayName = "VectorSearch"
  Component.afterDOMLoaded = "/* vector-search 浏览器引擎：以字符串内联进站点页面脚本运行。\n * 依赖仅：fetch（服务端检索 API）。\n * 架构（2026-09-22 用户要求）：检索改在服务器端执行（vector_tool/search_server.py），\n *   客户端不再下载 ~70MB 模型/pack/wasm，也不再本地推理；本引擎只负责\n *   UI（输入防抖 → POST /api/search → 渲染结果卡）+ 移动端 TOC 置顶补丁。\n */\n(() => {\n  const TOP_K = 8;\n\n  // ---------- API ----------\n  const API_BASE = (() => {\n    const base = (typeof document !== \"undefined\" &&\n      document.body?.dataset?.basepath) || \"\";\n    return base + \"/api/search\";\n  })();\n\n  // ---------- doc_path -> 站点 URL（对齐 slugifyFilePath/simplifySlug） ----------\n  function slugifyPath(s) {\n    return s.split(\"/\")\n      .map((seg) => seg.replace(/\\s/g, \"-\").replace(/&/g, \"-and-\")\n        .replace(/%/g, \"-percent\").replace(/\\?/g, \"\").replace(/#/g, \"\")\n        .replace(/[<>:\"|*]/g, \"\").toLowerCase())\n      .join(\"/\").replace(/\\/$/, \"\");\n  }\n\n  function docPathToUrl(p) {\n    let fp = p.replace(/^\\//, \"\").replace(/\\.(md|html)$/i, \"\");\n    let slug = slugifyPath(fp);\n    const segs = slug.split(\"/\");\n    if (segs.length >= 2 && segs[segs.length - 1] === segs[segs.length - 2]) {\n      segs[segs.length - 1] = \"index\";\n      slug = segs.join(\"/\");\n    }\n    if (slug === \"index\") slug = \"\";\n    else if (slug.endsWith(\"/index\")) slug = slug.slice(0, -\"index\".length);\n    else if (slug.endsWith(\"index\")) slug = slug.slice(0, -\"index\".length);\n    const base = document.body?.dataset?.basepath || \"\";\n    return base + \"/\" + slug;\n  }\n\n  // ---------- 搜索历史（localStorage） ----------\n  const HIST_KEY = \"vs-search-history\";\n  const HIST_MAX = 10;\n  function getHist() {\n    try { const h = JSON.parse(localStorage.getItem(HIST_KEY) || \"[]\"); return Array.isArray(h) ? h : []; }\n    catch (e) { return []; }\n  }\n  function addHist(q) {\n    try {\n      const h = getHist().filter((x) => x !== q);\n      h.unshift(q);\n      localStorage.setItem(HIST_KEY, JSON.stringify(h.slice(0, HIST_MAX)));\n    } catch (e) { /* localStorage 不可用时静默 */ }\n  }\n  function renderHist(box, input) {\n    const h = getHist();\n    if (!h.length) { box.innerHTML = \"\"; return; }\n    const chips = h.map((x) =>\n      '<button class=\"vs-chip\" type=\"button\" data-q=\"' + esc(x) + '\">' + esc(x) + \"</button>\").join(\"\");\n    box.innerHTML = '<div class=\"vs-history\">最近搜索：' + chips +\n      '<button class=\"vs-clear\" type=\"button\" title=\"清除历史\">✕</button></div>';\n    box.querySelectorAll(\".vs-chip\").forEach((b) => b.addEventListener(\"click\", () => {\n      const q2 = b.dataset.q;\n      input.value = q2;\n      runSearch(q2, box);\n    }));\n    const cl = box.querySelector(\".vs-clear\");\n    if (cl) cl.addEventListener(\"click\", () => {\n      try { localStorage.removeItem(HIST_KEY); } catch (e) {}\n      box.innerHTML = \"\";\n      input.focus();\n    });\n  }\n\n  // ---------- 检索 ----------\n  let seq = 0;\n  function renderError(box, msg, query) {\n    box.innerHTML = '<div class=\"vs-status vs-error\">检索失败：' + msg +\n      '<button class=\"vs-retry\" type=\"button\">重试</button></div>';\n    const btn = box.querySelector(\".vs-retry\");\n    if (btn) btn.addEventListener(\"click\", () => runSearch(query, box));\n  }\n  function closePanel(input, box) {\n    input.value = \"\";\n    box.innerHTML = \"\";\n    input.blur();\n  }\n  async function runSearch(query, box) {\n    const mySeq = ++seq;\n    if (!query || !query.trim()) { renderHist(box, document.querySelector(\".vector-search > .search-bar\")); return; }\n    addHist(query.trim());\n    box.innerHTML = '<div class=\"vs-status\">正在检索…</div>';\n    try {\n      const r = await fetch(API_BASE, {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify({ q: query.trim(), k: TOP_K }),\n      });\n      if (!r.ok) {\n        if (mySeq !== seq) return;\n        renderError(box, \"HTTP \" + r.status, query);\n        return;\n      }\n      const data = await r.json();\n      if (mySeq !== seq) return;\n      const hits = data.results || [];\n      if (!hits.length) { box.innerHTML = '<div class=\"vs-status\">无结果。试试换个词。</div>'; return; }\n      const terms = (data.terms || []).filter((t) => t.length >= 1);\n      const hl = (s) => {                       // 查询词高亮（s 已 esc；terms 逐词高亮）\n        let out = s;\n        for (const t of terms) {\n          const qt = esc(t);\n          if (!qt || !out.includes(qt)) continue;\n          out = out.split(qt).join('<mark class=\"vs-hl\">' + qt + \"</mark>\");\n        }\n        return out;\n      };\n      const near = (text, toks, w) => {          // 围绕首个命中词截 snippet\n        let at = -1;\n        for (const t of toks) {\n          if (!t) continue;\n          const i = text.indexOf(t);\n          if (i >= 0 && (at < 0 || i < at)) at = i;\n        }\n        if (at < 0) return text.slice(0, 150);\n        const s = Math.max(0, at - w);\n        return (s > 0 ? \"…\" : \"\") + text.slice(s, Math.min(text.length, at + w + 90));\n      };\n\n      const html = [];\n      const seen = new Set();\n      for (const h of hits) {\n        if (seen.has(h.doc_path)) continue;      // 双保险：同文档只出一卡\n        seen.add(h.doc_path);\n        const url = docPathToUrl(h.doc_path);\n        // 标题优先文档文件名（短、稳定）；heading 太长时不用\n        const fileTitle = h.doc_path.split(\"/\").pop().replace(/\\.md$/i, \"\")\n          .replace(/^\\d{3}-/, \"\");\n        const title = (h.heading && h.heading.length <= 24) ? h.heading : fileTitle;\n        const raw = (h.text || \"\").replace(/[#>*`\\[\\]!]/g, \"\").replace(/\\s+/g, \" \").trim();\n        const snip = near(raw, terms.length ? terms : [query.trim()], 60);\n        html.push(\n          '<a class=\"result-card\" href=\"' + url + '\">' +\n          '<h3 class=\"card-title\">' + hl(esc(title)) + \"</h3>\" +\n          '<p class=\"card-description\">' + hl(esc(snip)) + \"</p>\" +\n          '<p class=\"vs-meta\">' + esc((h.domain || \"\").replace(/\\.pack$/, \"\")) + \" · \" + esc(h.doc_path) +\n          \" · 相似度 \" + h.score.toFixed(3) + \"</p></a>\");\n      }\n      if (mySeq !== seq) return;\n      box.innerHTML = '<div class=\"vs-count\"><span class=\"vs-n\">找到 ' + hits.length + ' 条相关结果</span>' +\n        '<button class=\"vs-close\" type=\"button\" title=\"关闭\">✕</button></div>' + html.join(\"\");\n      const ic = box.querySelector(\".vs-close\");\n      if (ic) ic.addEventListener(\"click\", () => {\n        const inp = document.querySelector(\".vector-search > .search-bar\");\n        if (inp) closePanel(inp, box);\n      });\n    } catch (e) {\n      if (mySeq === seq) renderError(box, (e && e.message ? e.message : String(e)), query);\n    }\n  }\n\n  const esc = (s) => String(s).replace(/&/g, \"&amp;\").replace(/</g, \"&lt;\")\n    .replace(/>/g, \"&gt;\").replace(/\"/g, \"&quot;\");\n\n  // ---------- 移动端 TOC 置顶（站点级补丁） ----------\n  // Quartz 在 <1200px 下 `.sidebar.right>.toc{display:none}` 隐藏目录，且右栏被\n  // 排在正文之后。此处把 TOC 节点搬进正文顶部的 <details> 折叠块（桌面自动还原）。\n  const tocWide = window.matchMedia(\"(min-width: 1200px)\");\n  function placeToc() {\n    const article = document.querySelector(\".center article\") || document.querySelector(\"article\");\n    if (!article) return;\n    const moved = document.querySelector(\".vs-mobile-toc\");\n    const toc = (moved && moved.querySelector(\".toc\")) ||\n      document.querySelector(\".sidebar.right > .toc\");\n    if (!toc || !toc.querySelector(\"a\")) return;  // 无标题的笔记不显示空目录框\n    if (!tocWide.matches) {\n      if (moved) return;\n      const wrap = document.createElement(\"details\");\n      wrap.className = \"vs-mobile-toc\";\n      wrap.open = true;\n      const sum = document.createElement(\"summary\");\n      sum.textContent = \"目录\";\n      wrap.appendChild(sum);\n      wrap.appendChild(toc);\n      article.insertBefore(wrap, article.firstChild);\n    } else if (moved) {\n      const sb = document.querySelector(\".sidebar.right\");\n      const graph = sb && sb.querySelector(\".graph\");\n      if (graph) graph.after(toc);\n      else if (sb) sb.appendChild(toc);\n      moved.remove();\n    }\n  }\n  if (tocWide.addEventListener) tocWide.addEventListener(\"change\", placeToc);\n  else if (tocWide.addListener) tocWide.addListener(placeToc);\n\n  // ---------- UI 挂载 ----------\n  function mount() {\n    document.querySelectorAll(\".vector-search\").forEach((root) => {\n      if (root.dataset.vsMounted) return;\n      root.dataset.vsMounted = \"1\";\n      const input = root.querySelector(\".search-bar\");\n      const box = root.querySelector(\".vector-results\");\n      if (!input || !box) return;\n      let timer = null;\n      input.addEventListener(\"input\", () => {\n        clearTimeout(timer);\n        timer = setTimeout(() => runSearch(input.value, box), 250);\n      });\n      input.addEventListener(\"keydown\", (e) => {\n        if (e.key === \"Escape\") { closePanel(input, box); return; }\n        const cards = Array.from(box.querySelectorAll(\".result-card\"));\n        if (!cards.length) return;\n        let idx = cards.findIndex((c) => c.classList.contains(\"vs-active\"));\n        if (e.key === \"ArrowDown\") {\n          e.preventDefault();\n          idx = Math.min(idx + 1, cards.length - 1);\n          if (idx < 0) idx = 0;\n          activate(cards, idx);\n        } else if (e.key === \"ArrowUp\") {\n          e.preventDefault();\n          idx = idx < 0 ? cards.length - 1 : idx - 1;\n          activate(cards, idx);\n        } else if (e.key === \"Enter\" && idx >= 0) {\n          e.preventDefault();\n          cards[idx].click();\n        }\n      });\n      function activate(cards, idx) {\n        cards.forEach((c, i) => c.classList.toggle(\"vs-active\", i === idx));\n        cards[idx].scrollIntoView({ block: \"nearest\" });\n      }\n      input.addEventListener(\"focus\", () => {\n        if (!input.value.trim() && !box.querySelector(\".vs-history\")) renderHist(box, input);\n      });\n    });\n    placeToc();\n  }\n\n  // 点击面板外关闭结果（全屏浮层形态下必须有，模块级只注册一次）\n  document.addEventListener(\"click\", (e) => {\n    document.querySelectorAll(\".vector-search\").forEach((root) => {\n      if (root.contains(e.target)) return;\n      const b = root.querySelector(\".vector-results\");\n      if (b && b.innerHTML) b.innerHTML = \"\";\n    });\n  });\n\n  window.__vectorSearch = { runSearch, mount, state: { ready: true } };\n  if (document.readyState === \"loading\") document.addEventListener(\"DOMContentLoaded\", mount);\n  else mount();\n  document.addEventListener(\"nav\", mount);\n})();\n"
  Component.css = ".vector-search {\n  min-width: fit-content;\n  max-width: 14rem;\n  position: relative;\n}\n.vector-search > input.search-bar {\n  width: 100%;\n  box-sizing: border-box;\n  padding: 0.4em 0.8em;\n  font-family: var(--bodyFont);\n  color: var(--dark);\n  font-size: 1em;\n  border: 1px solid var(--lightgray);\n  border-radius: 6px;\n  background: var(--light);\n}\n.vector-search > input.search-bar:focus {\n  outline: none;\n  border-color: var(--tertiary);\n}\n.vector-search > .vector-results:empty {\n  display: none;\n}\n/* 结果面板：与内置搜索（.search-container/.search-space）一致的全屏浮层范式\n   —— 居中 65% 宽（移动端 90%）、12vh 起、带模糊遮罩，而不是贴着输入框的窄下拉。 */\n.vector-search > .vector-results:not(:empty) {\n  position: fixed;\n  top: 12vh;\n  left: 50%;\n  right: auto;\n  transform: translateX(-50%);\n  width: 65%;\n  max-width: none;\n  max-height: 70vh;\n  overflow-y: auto;\n  z-index: calc(var(--search-z-index, 999) + 3);\n  background: var(--light);\n  border: 1px solid var(--lightgray);\n  border-radius: 7px;\n  box-shadow: 0 14px 50px rgba(27, 33, 48, 0.12), 0 10px 30px rgba(27, 33, 48, 0.16);\n}\n/* 遮罩：结果面板打开时压暗页面（与内置搜索的 backdrop-filter 一致）\n   pointer-events:none 必需——伪元素属于 .vector-search，会吞掉全屏点击，\n   导致「点面板外关闭」失效且页面链接点不动。 */\n.vector-search:has(> .vector-results:not(:empty))::before {\n  content: \"\";\n  position: fixed;\n  inset: 0;\n  background: rgba(27, 33, 48, 0.12);\n  -webkit-backdrop-filter: blur(4px);\n  backdrop-filter: blur(4px);\n  pointer-events: none;\n  z-index: calc(var(--search-z-index, 999) + 2);\n}\n@media (max-width: 800px) {\n  /* 移动端：结果面板真正全屏（顶部 8vh 留给导航栏输入框），可滚动 */\n  .vector-search > .vector-results:not(:empty) {\n    position: fixed;\n    top: 8vh;\n    left: 0;\n    right: 0;\n    bottom: 0;\n    transform: none;\n    width: 100%;\n    max-width: none;\n    max-height: none;\n    border-radius: 0;\n    border: none;\n    border-top: 1px solid var(--lightgray);\n  }\n  /* 全屏时关闭按钮可见（特异性高于基础 display:none，后者在下方定义） */\n  .vector-search .vector-results .vs-close {\n    display: inline-block;\n  }\n}\n/* 结果面板滚动条（细） */\n.vector-search > .vector-results::-webkit-scrollbar {\n  width: 6px;\n}\n.vector-search > .vector-results::-webkit-scrollbar-thumb {\n  background: var(--lightgray);\n  border-radius: 3px;\n}\n/* 关闭按钮：桌面隐藏，移动端显示 */\n.vector-search .vs-close {\n  display: none;\n  margin-left: 0.6em;\n  padding: 0.05em 0.5em;\n  cursor: pointer;\n  border: 1px solid var(--lightgray);\n  border-radius: 5px;\n  background: transparent;\n  color: var(--gray);\n  font-size: 0.9em;\n}\n.vector-search .vs-count {\n  padding: 0.2em 0.9em;\n  font-size: 0.85em;\n  color: var(--gray);\n  border-bottom: 1px solid var(--lightgray);\n  display: flex;\n  align-items: center;\n}\n.vector-search .vs-count > span.vs-n {\n  margin-right: auto;\n}\n/* 键盘导航选中态 + hover 过渡 */\n.vector-search .result-card {\n  transition: background 0.12s ease;\n}\n.vector-search .result-card.vs-active {\n  background: var(--lightgray);\n  box-shadow: inset 0 0 0 2px var(--tertiary);\n}\n.vector-search .result-card:hover {\n  background: var(--lightgray);\n}\n/* 移动端 TOC 置顶块（节点由引擎 placeToc() 搬入正文顶部） */\n.vs-mobile-toc {\n  margin: 0 0 1.25rem;\n  padding: 0.35rem 0.75rem;\n  border: 1px solid var(--lightgray);\n  border-radius: 6px;\n  background: var(--light);\n}\n.vs-mobile-toc > summary {\n  cursor: pointer;\n  padding: 0.3rem 0;\n  font-weight: 600;\n  color: var(--dark);\n}\n.vs-mobile-toc .toc {\n  display: flex;\n  flex-direction: column;\n  min-height: 0;\n}\n.vs-mobile-toc .toc-content {\n  max-height: 40vh;\n  overflow-y: auto;\n}\n.vs-mobile-toc .toc-header {\n  display: none;\n}\n.vector-search .vs-history {\n  padding: 0.4em 0.9em;\n  font-size: 0.85em;\n  color: var(--gray);\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 0.4em;\n}\n.vector-search .vs-chip {\n  padding: 0.15em 0.7em;\n  font-size: 0.95em;\n  cursor: pointer;\n  border: 1px solid var(--lightgray);\n  border-radius: 999px;\n  background: transparent;\n  color: inherit;\n}\n.vector-search .vs-chip:hover {\n  border-color: var(--gray);\n  background: var(--lightgray);\n}\n.vector-search .vs-clear {\n  margin-left: auto;\n  padding: 0.1em 0.5em;\n  cursor: pointer;\n  border: none;\n  background: transparent;\n  color: var(--gray);\n  font-size: 0.9em;\n}\n.vector-search .vs-retry {\n  margin-left: 0.6em;\n  padding: 0.1em 0.7em;\n  font-size: 0.9em;\n  cursor: pointer;\n  border: 1px solid var(--gray);\n  border-radius: 5px;\n  background: transparent;\n  color: inherit;\n}\n.vector-search .vs-hl {\n  background: rgba(255, 213, 79, .38);\n  border-radius: 3px;\n  padding: 0 1px;\n}\n.vector-search .vs-status {\n  padding: 0.5em 0.9em;\n  color: var(--gray);\n  font-size: 0.9em;\n}\n.vector-search .vs-status.vs-error {\n  color: var(--secondary);\n}\n.vector-search .result-card {\n  display: block;\n  padding: 0.6em 0.9em;\n  text-decoration: none;\n  color: var(--dark);\n  border-bottom: 1px solid var(--lightgray);\n}\n.vector-search .result-card:last-child {\n  border-bottom: none;\n}\n.vector-search .result-card:hover {\n  background: var(--lightgray);\n}\n.vector-search .result-card > h3.card-title {\n  margin: 0;\n  font-size: 0.95em;\n  color: var(--secondary);\n}\n.vector-search .result-card > p.card-description {\n  margin: 0.25em 0 0;\n  font-size: 0.85em;\n  color: var(--gray);\n  display: -webkit-box;\n  -webkit-line-clamp: 2;\n  -webkit-box-orient: vertical;\n  overflow: hidden;\n}\n.vector-search .result-card > p.vs-meta {\n  margin: 0.25em 0 0;\n  font-size: 0.75em;\n  color: var(--tertiary);\n}\n"
  return Component
}
